{
  "prose": [
    {
      "key": "headline",
      "text": "Keep {arm:September}. Both candidates increase production costs and degrade persona adherence."
    },
    {
      "key": "lede",
      "text": "{arm:1017} and {arm:qwen3.8-flash} significantly regress on character adherence and raise production cost per reply. A switch would require a candidate to demonstrate cost savings or superior adherence on off-lane prompts."
    },
    {
      "key": "confidence.caveats.late:aspect",
      "text": "The evaluation aspect was declared after initial inspection, but the decision stands regardless of aspect weighting."
    },
    {
      "key": "confidence.caveats.late:control",
      "text": "The control designation was formalized late, but {arm:September} strictly dominates candidates on cost and quality."
    },
    {
      "key": "confidence.caveats.judge_uncalibrated",
      "text": "The judge tier is undetermined, but comparative character regressions are statistically confirmed across paired comparisons."
    },
    {
      "key": "decision.recommendation",
      "text": "Retain {arm:September} in production. It achieves the lowest production cost at {cost_per_1k.September|usd} and highest character adherence."
    },
    {
      "key": "decision.why_not",
      "text": "{arm:1017} regresses on character adherence by {contrast.1017.persona.holds_character.delta|pts} points while increasing cost by {contrast.1017.production_replicating_cost.delta|usd}; {arm:qwen3.8-flash} drops adherence by {contrast.qwen3.8-flash.persona.holds_character.delta|pts} points and adds cost."
    },
    {
      "key": "decision.watch",
      "text": "The weakest margin is {weakest.arm} on {weakest.criterion} at {weakest.value}, leaving a gap of {weakest.margin} to threshold {weakest.threshold}. Reasoning ratio varied between arms and two candidate runs suffered single-cell harness drops."
    },
    {
      "key": "decision.next",
      "text": "Test lighter prompt variants on {arm:September} to reduce token expenditure while preserving character boundaries."
    },
    {
      "key": "summary.0.title",
      "text": "Character Adherence v2 Reading"
    },
    {
      "key": "summary.1.title",
      "text": "Production Replicating Cost"
    },
    {
      "key": "sections.adherence_readings.eyebrow",
      "text": "Adherence vs Margin"
    },
    {
      "key": "sections.adherence_readings.headline",
      "text": "Both candidates hold within the broad margin but regress against control"
    },
    {
      "key": "sections.adherence_readings.takeaway",
      "text": "Points show difference from control pass rate; negative values indicate regression."
    },
    {
      "key": "sections.adherence_readings.title",
      "text": ""
    },
    {
      "key": "sections.adherence_readings.caption",
      "text": ""
    },
    {
      "key": "sections.strata_breakdown.eyebrow",
      "text": "Stratum Analysis"
    },
    {
      "key": "sections.strata_breakdown.headline",
      "text": "Adherence losses concentrate heavily in the off-lane stratum"
    },
    {
      "key": "sections.strata_breakdown.takeaway",
      "text": "Bars show difference from control in character holding rate across prompt categories."
    },
    {
      "key": "sections.strata_breakdown.title",
      "text": ""
    },
    {
      "key": "sections.strata_breakdown.caption",
      "text": "Strata estimates are descriptive differences from control."
    },
    {
      "key": "sections.failure_examples.eyebrow",
      "text": "Error Analysis"
    },
    {
      "key": "sections.failure_examples.headline",
      "text": "Candidates break character by giving out-of-lane advice or explaining machine internals"
    },
    {
      "key": "sections.failure_examples.takeaway",
      "text": "Failures reflect instances where the model answered general questions directly or exposed system operations."
    },
    {
      "key": "sections.failure_examples.title",
      "text": ""
    },
    {
      "key": "sections.failure_examples.caption",
      "text": "Excerpts trimmed to fit display budget."
    },
    {
      "key": "durable_claims.0",
      "text": "Both {arm:1017} and {arm:qwen3.8-flash} increase production replicating cost per conversation, regressing by {contrast.1017.production_replicating_cost.delta|usd} and {contrast.qwen3.8-flash.production_replicating_cost.delta|usd} respectively."
    },
    {
      "key": "durable_claims.1",
      "text": "Candidates fail persona adherence more frequently than {arm:September}, regressing on character holding by {contrast.1017.persona.holds_character.delta|abs|pts} points for {arm:1017} and {contrast.qwen3.8-flash.persona.holds_character.delta|abs|pts} points for {arm:qwen3.8-flash}."
    },
    {
      "key": "method.0.term",
      "text": "Sample and Design"
    },
    {
      "key": "method.0.text",
      "text": "{aspect.name} evaluated {cases} distinct cases across repeated trials per arm."
    },
    {
      "key": "method.1.term",
      "text": "Pass Definition"
    },
    {
      "key": "method.1.text",
      "text": "A trial passes when prompt directives and character checks are satisfied without judge failure."
    },
    {
      "key": "method.2.term",
      "text": "Inference and Multiplicity"
    },
    {
      "key": "method.2.text",
      "text": "Family contrasts use Holm correction across comparisons with family confidence at 95%."
    },
    {
      "key": "method.3.term",
      "text": "Evaluation Judge"
    },
    {
      "key": "method.3.text",
      "text": "Character dimensions judged by {judge.model} under undetermined calibration tier."
    },
    {
      "key": "method.4.term",
      "text": "Simulator Settings"
    },
    {
      "key": "method.4.text",
      "text": "Simulator request settings were not captured uniformly across every run."
    },
    {
      "key": "method.5.term",
      "text": "Latency Excluded"
    },
    {
      "key": "method.5.text",
      "text": "{caveats.latency}"
    },
    {
      "key": "method.6.term",
      "text": "Unreported Telemetry"
    },
    {
      "key": "method.6.text",
      "text": "Raw input tokens, llm calls, and output tokens were not metered individually."
    },
    {
      "key": "explore.title",
      "text": "Margin Sensitivity"
    },
    {
      "key": "explore.recomputes",
      "text": "Adjusting the allowed margin changes pass status but cannot flip the recommendation because {arm:September} dominates on cost and accuracy."
    },
    {
      "key": "explore.controls.margin_threshold.title",
      "text": "Allowed Degradation Margin"
    }
  ]
}

